create or replace function public.hrms_role() returns text language sql stable security definer set search_path=public as $$ select coalesce((select lower(role) from public.profiles where id=auth.uid() and active),'employee') $$;
revoke all on function public.hrms_role() from public, anon; grant execute on function public.hrms_role() to authenticated;
create or replace function public.hrms_is_hr() returns boolean language sql stable security definer set search_path=public as $$ select public.hrms_role() in ('administrator','hr','hr_manager') $$;
revoke all on function public.hrms_is_hr() from public, anon; grant execute on function public.hrms_is_hr() to authenticated;

alter table public.departments enable row level security; create policy "read departments" on public.departments for select using (auth.uid() is not null); create policy "manage departments" on public.departments for all using (public.hrms_is_hr()) with check (public.hrms_is_hr());
alter table public.profiles enable row level security; create policy "read own profile" on public.profiles for select using (id=auth.uid() or public.hrms_is_hr()); create policy "admin profiles" on public.profiles for all using (public.hrms_role()='administrator') with check (public.hrms_role()='administrator');
alter table public.employees enable row level security; create policy "read employee" on public.employees for select using (user_id=auth.uid() or public.hrms_is_hr()); create policy "manage employees" on public.employees for all using (public.hrms_is_hr()) with check (public.hrms_is_hr());
alter table public.employee_requests enable row level security; create policy "requests scope" on public.employee_requests for all using (public.hrms_is_hr() or exists(select 1 from employees e where e.id=employee_id and e.user_id=auth.uid())) with check (public.hrms_is_hr() or exists(select 1 from employees e where e.id=employee_id and e.user_id=auth.uid()));
alter table public.leave_requests enable row level security; create policy "leave scope" on public.leave_requests for all using (public.hrms_is_hr() or exists(select 1 from employees e where e.id=employee_id and e.user_id=auth.uid())) with check (public.hrms_is_hr() or exists(select 1 from employees e where e.id=employee_id and e.user_id=auth.uid()));
alter table public.leave_balances enable row level security; create policy "balances scope" on public.leave_balances for select using (public.hrms_is_hr() or exists(select 1 from employees e where e.id=employee_id and e.user_id=auth.uid())); create policy "manage balances" on public.leave_balances for all using (public.hrms_is_hr()) with check (public.hrms_is_hr());
alter table public.employment_contracts enable row level security; create policy "contracts scope" on public.employment_contracts for select using (public.hrms_is_hr() or exists(select 1 from employees e where e.id=employee_id and e.user_id=auth.uid())); create policy "manage contracts" on public.employment_contracts for all using(public.hrms_is_hr()) with check(public.hrms_is_hr());
alter table public.onboarding_tasks enable row level security; create policy "tasks scope" on public.onboarding_tasks for select using(public.hrms_is_hr() or exists(select 1 from employees e where e.id=employee_id and e.user_id=auth.uid())); create policy "manage tasks" on public.onboarding_tasks for all using(public.hrms_is_hr()) with check(public.hrms_is_hr());
alter table public.hr_cases enable row level security; create policy "hr cases only" on public.hr_cases for all using(public.hrms_is_hr()) with check(public.hrms_is_hr());
alter table public.engagement_surveys enable row level security; create policy "surveys read" on public.engagement_surveys for select using(auth.uid() is not null); create policy "manage surveys" on public.engagement_surveys for all using(public.hrms_is_hr()) with check(public.hrms_is_hr());
alter table public.survey_responses enable row level security; create policy "responses scope" on public.survey_responses for all using(public.hrms_is_hr() or exists(select 1 from employees e where e.id=employee_id and e.user_id=auth.uid())) with check(public.hrms_is_hr() or exists(select 1 from employees e where e.id=employee_id and e.user_id=auth.uid()));
alter table public.retention_actions enable row level security; create policy "retention hr only" on public.retention_actions for all using(public.hrms_is_hr()) with check(public.hrms_is_hr());
alter table public.exit_cases enable row level security; create policy "exit scope" on public.exit_cases for all using(public.hrms_is_hr() or exists(select 1 from employees e where e.id=employee_id and e.user_id=auth.uid())) with check(public.hrms_is_hr());
alter table public.exit_checklist_items enable row level security; create policy "checklist hr only" on public.exit_checklist_items for all using(public.hrms_is_hr()) with check(public.hrms_is_hr());
alter table public.notifications enable row level security; create policy "own notifications" on public.notifications for select using(user_id=auth.uid()); create policy "hr notifications" on public.notifications for insert with check(public.hrms_is_hr());
alter table public.audit_events enable row level security; create policy "audit hr only" on public.audit_events for select using(public.hrms_is_hr()); create policy "audit insert" on public.audit_events for insert with check(auth.uid()=actor_id or public.hrms_is_hr());
